#!/usr/bin/env python3
"""
Final fixed solver:
- Add 'started' flag to track whether non-zero digit seen yet
- Leading zeros (when started=False) are stripped by toPath
- This affects the effective path length
"""

import socket
import sys

sys.set_int_max_str_digits(0)
directions = "LRUD"

print("Connecting...")
sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
sock.settimeout(10)
sock.connect(("192.168.2.214", 9999))

def recv_until(sock, marker):
    data = b""
    while marker not in data:
        chunk = sock.recv(4096)
        if not chunk:
            break
        data += chunk
    return data

def recv_line(sock):
    data = b""
    while not data.endswith(b"\n"):
        chunk = sock.recv(1)
        if not chunk:
            break
        data += chunk
    return data.decode().strip()

def send_line(sock, msg):
    sock.sendall((msg + "\n").encode())

data = recv_until(sock, b"Options: 1. Decrypt 2. Check answer.\n")
lines = data.decode().split("\n")
n_val = int(lines[1].split("= ")[1])
e_val = int(lines[2].split("= ")[1])
enc_hex = lines[3]
enc = int(enc_hex, 16)
print(f"n={n_val}, e={e_val}")

def oracle_query(ct):
    send_line(sock, "1")
    recv_until(sock, b"Ciphertext in hex: ")
    send_line(sock, hex(ct))
    resp = recv_line(sock)
    resp = resp.strip("()")
    dx, dy = resp.split(",")
    return int(dx.strip()), int(dy.strip())

all_multipliers = list(range(1, 33))
oracle_results = {}
for k in all_multipliers:
    mult = pow(k, e_val, n_val)
    ct = (enc * mult) % n_val
    dx, dy = oracle_query(ct)
    oracle_results[k] = (dx, dy)
    print(f"k={k:3d}: ({dx:4d}, {dy:4d})")

def make_trans(k):
    def trans(d, c):
        p = k * d + c
        return (p % 4, p // 4,
                -1 if p%4==0 else (1 if p%4==1 else 0),
                1 if p%4==2 else (-1 if p%4==3 else 0))
    return trans

def make_residual(k):
    def res(c):
        dx, dy = 0, 0
        while c > 0:
            b = c % 4
            c //= 4
            if b == 0: dx -= 1
            elif b == 1: dx += 1
            elif b == 2: dy += 1
            elif b == 3: dy -= 1
        return dx, dy
    return res

MAX_N = 64

# Modified k=1 DP: accounts for leading zero stripping
# State: started (bool) - whether non-zero digit seen
# For N remaining positions and started flag, what (dx,dy) are achievable?
dp_k1_started = [{False: set(), True: set()} for _ in range(MAX_N + 1)]
for N in range(MAX_N + 1):
    for started in [False, True]:
        result = set()
        for dx in range(-N, N+1):
            max_dy = N - abs(dx)
            for dy in range(-max_dy, max_dy+1):
                if (N - abs(dx) - abs(dy)) % 2 == 0:
                    if started:
                        result.add((dx, dy))
                    else:
                        # If not started, we might stay not started (all zeros)
                        # In that case, N zeros → toPath(0) → "L" → (-1,0)
                        # But we can also start at any point
                        # For simplicity, use the same set but allow (dx,dy) or...
                        # Actually, if not started, the achievable set is:
                        # EITHER: all zeros → (-1, 0) (from toPath(0))
                        # OR: start at position k (1 ≤ k ≤ N) with first non-zero digit
                        # This is complex. Let me just use the full set as approximation
                        # and handle zero-stripping in verification.
                        result.add((dx, dy))
        dp_k1_started[N][started] = result

# For pruning, I'll use the simpler DP (without zero-stripping) and handle
# the mismatch via relaxed checking at MSB positions.

dp_k1 = [set() for _ in range(MAX_N + 1)]
for N in range(MAX_N + 1):
    for dx in range(-N, N+1):
        max_dy = N - abs(dx)
        for dy in range(-max_dy, max_dy+1):
            if (N - abs(dx) - abs(dy)) % 2 == 0:
                dp_k1[N].add((dx, dy))

def build_dp(k):
    trans = make_trans(k)
    residual_fn = make_residual(k)
    max_c = min(k, 5)
    dp = [{c: set() for c in range(max_c + 1)} for _ in range(MAX_N + 1)]
    for c in range(max_c + 1):
        dp[0][c] = {residual_fn(c)}
    for N in range(1, MAX_N + 1):
        for c in range(max_c + 1):
            result = set()
            for d in range(4):
                _, co, dxc, dyc = trans(d, c)
                if co <= max_c:
                    for (rdx, rdy) in dp[N-1][co]:
                        result.add((dxc + rdx, dyc + rdy))
            dp[N][c] = result
    return dp

print("Building DP...")
dp_k2 = build_dp(2)
dp_k3 = build_dp(3)
print("DP ready.")

def in_dp1(dp_set, dx, dy):
    return (dx, dy) in dp_set or (dx + 1, dy) in dp_set

def in_dp23(dp_dict, carry, dx, dy):
    if carry not in dp_dict:
        return False
    s = dp_dict[carry]
    return (dx, dy) in s or (dx + 1, dy) in s

trans_k1 = lambda d, c: (d, 0, [-1,1,0,0][d], [0,0,1,-1][d])
trans_k2 = make_trans(2)
trans_k3 = make_trans(3)

# Verification that EXACTLY matches server's toPath
def toPath(x):
    s = bin(x)[2:]
    if len(s) % 2 == 1:
        s = "0" + s
    path = ""
    for i in range(0, len(s), 2):
        path += directions[int(s[i:i+2], 2)]
    return path

def final_position(path):
    return (path.count("R") - path.count("L"), path.count("U") - path.count("D"))

def verify_via_toPath(digits, k):
    """Compute m*k from digits and get final_position via actual toPath."""
    m = 0
    for i, d in enumerate(digits):
        m += d * (4 ** i)
    mk = m * k
    return final_position(toPath(mk))

def verify_full_via_toPath(digits):
    """Verify candidate against all oracle results using actual toPath."""
    for k in all_multipliers:
        if verify_via_toPath(digits, k) != oracle_results[k]:
            return False
    return True

# Beam search with zero-stripping awareness
NUM_POSITIONS = 64
BEAM_WIDTH = 50000

targets = oracle_results

# State: (digits, started, dx1, dy1, c2, dx2, dy2, c3, dx3, dy3)
# started: bool, whether we've seen a non-zero digit yet (for zero-stripping)
initial = ((), False, 0, 0, 0, 0, 0, 0, 0, 0)
states = {initial}

for pos in range(NUM_POSITIONS):
    remaining = NUM_POSITIONS - pos - 1
    new_states = {}

    if pos % 4 == 0:
        print(f"  Pos {pos}: {len(states)} states")

    for state in states:
        digits, started, dx1, dy1, c2, dx2, dy2, c3, dx3, dy3 = state

        for d in range(4):
            new_started = started or (d != 0)

            # k=1: if not started and d=0, this digit gets stripped (contributes nothing)
            if not started and d == 0:
                ndx1, ndy1 = dx1, dy1
            else:
                ndx1 = dx1 + [-1, 1, 0, 0][d]
                ndy1 = dy1 + [0, 0, 1, -1][d]

            # For pruning with k=1, need to handle zero-stripping
            if remaining == 0:
                # Last position - exact match required
                if (ndx1, ndy1) != targets[1]:
                    # Might match with padding adjustment
                    if (ndx1, ndy1) != (targets[1][0] + 1, targets[1][1]):
                        # Or with zero-stripping: if !new_started, result is toPath(0) = (-1,0)
                        if not new_started:
                            if targets[1] != (-1, 0) and targets[1] != (0, 0):
                                continue
                        else:
                            continue
            else:
                # Use relaxed DP check
                rem_dx1 = targets[1][0] - ndx1
                rem_dy1 = targets[1][1] - ndy1
                if not new_started and remaining > 0:
                    # If not started yet, remaining positions could all be zero
                    # Result would be toPath(0) = (-1, 0) or toPath(small_number)
                    # Use relaxed check
                    if not in_dp1(dp_k1[remaining], rem_dx1, rem_dy1):
                        continue
                else:
                    if not in_dp1(dp_k1[remaining], rem_dx1, rem_dy1):
                        continue

            # k=2
            _, co2, dx2c, dy2c = trans_k2(d, c2)
            ndx2 = dx2 + dx2c
            ndy2 = dy2 + dy2c
            if co2 > 1 or not in_dp23(dp_k2[remaining], co2, targets[2][0] - ndx2, targets[2][1] - ndy2):
                continue

            # k=3
            _, co3, dx3c, dy3c = trans_k3(d, c3)
            ndx3 = dx3 + dx3c
            ndy3 = dy3 + dy3c
            if co3 > 3 or not in_dp23(dp_k3[remaining], co3, targets[3][0] - ndx3, targets[3][1] - ndy3):
                continue

            new_digits = digits + (d,)
            key = (new_started, ndx1, ndy1, co2, ndx2, ndy2, co3, ndx3, ndy3)
            if key not in new_states:
                new_states[key] = new_digits

    states_list = list(new_states.items())
    if len(states_list) > BEAM_WIDTH:
        def score(item):
            (started, ndx1, ndy1, co2, ndx2, ndy2, co3, ndx3, ndy3), _ = item
            return (abs(targets[1][0]-ndx1) + abs(targets[1][1]-ndy1) +
                    abs(targets[2][0]-ndx2) + abs(targets[2][1]-ndy2) +
                    abs(targets[3][0]-ndx3) + abs(targets[3][1]-ndy3))
        states_list.sort(key=score)
        states_list = states_list[:BEAM_WIDTH]

    states = set()
    for key, digits in states_list:
        started, ndx1, ndy1, co2, ndx2, ndy2, co3, ndx3, ndy3 = key
        states.add((digits, started, ndx1, ndy1, co2, ndx2, ndy2, co3, ndx3, ndy3))

    print(f"    -> {len(states)} survive")
    if len(states) == 0:
        print("  DEAD END!")
        break

print(f"\nDone: {len(states)} candidates")

# Verify using actual toPath
found = False
for state in list(states):
    digits, started, _, _, _, _, _, _, _, _ = state
    if verify_full_via_toPath(digits):
        print("SOLUTION FOUND!")
        dlist = list(digits)
        while len(dlist) > 1 and dlist[-1] == 0:
            dlist.pop()
        path = "".join(directions[x] for x in reversed(dlist))
        print(f"Path: {path} (len={len(path)})")
        solution = "L" * (64 - len(path)) + path
        print(f"Solution: {solution}")

        print("Submitting...")
        send_line(sock, "2")
        recv_until(sock, b"Solution: ")
        send_line(sock, solution)
        resp = recv_line(sock)
        print(f"Response: {resp}")
        found = True
        break

if not found:
    print("No solution found.")
    # Debug top candidate
    if len(states) > 0:
        state = list(states)[0]
        digits, started, _, _, _, _, _, _, _, _ = state
        print(f"Top candidate started={started}, first digits: {str(digits[:10])}")
        for k in [1,2,3,4,5]:
            pos = verify_via_toPath(digits, k)
            match = "✓" if pos == oracle_results[k] else "✗"
            print(f"  k={k}: computed={pos} oracle={oracle_results[k]} {match}")

sock.close()

