        states_list.sort(key=score)
        states_list=states_list[:BEAM_WIDTH]

    states=set()
    for key,digits in states_list:
        st,ndx1,ndy1,co2,ndx2,ndy2,co3,ndx3,ndy3,co5,ndx5,ndy5=key
        states.add((digits,st,ndx1,ndy1,co2,ndx2,ndy2,co3,ndx3,ndy3,co5,ndx5,ndy5))

    print(f"    -> {len(states)} survive")
