def fast_fp_toPath(x):
    """Compute final_position(toPath(x)) using integer ops (no strings)."""
    if x == 0:
        return (-1, 0)  # toPath(0) = "L"

    # Find bit length
    L = x.bit_length()

    dx, dy = 0, 0

    if L % 2 == 1:
        # Padding: first chunk is (0, MSB)
        msb = (x >> (L - 1)) & 1
        # Chunk = (0, msb) → only R (01) or L (00) possible
        if msb == 0:  # 00 → L
            dx -= 1
        else:  # 01 → R
            dx += 1
        L -= 1  # One bit consumed

    # Now process remaining bits in pairs from MSB to LSB
    while L > 0:
        chunk = (x >> (L - 2)) & 3
        if chunk == 0: dx -= 1
        elif chunk == 1: dx += 1
        elif chunk == 2: dy += 1
        elif chunk == 3: dy -= 1
        L -= 2

    return (dx, dy)

# Quick test
def toPath(x):
    s=bin(x)[2:]
    if len(s)%2==1:s="0"+s
    return "".join(directions[int(s[i:i+2],2)] for i in range(0,len(s),2))
def fp(p):return(p.count("R")-p.count("L"),p.count("U")-p.count("D"))

for test_x in [0, 1, 2, 3, 4, 5, 100, 1000, 123456]:
