"""DFS with DP pruning - should find solution since DP is exact."""
import socket, sys
sys.set_int_max_str_digits(0)
directions="LRUD"

sock=socket.socket(socket.AF_INET,socket.SOCK_STREAM)
sock.settimeout(10);sock.connect(("192.168.2.214",9999))

def ru(s,m):
    d=b""
    while m not in d:
        c=s.recv(4096)
        if not c:break
        d+=c
    return d
def rl(s):
    d=b""
    while not d.endswith(b"\n"):
        c=s.recv(1)
        if not c:break
        d+=c
    return d.decode().strip()
def sl(s,m):s.sendall((m+"\n").encode())

data=ru(sock,b"Options: 1. Decrypt 2. Check answer.\n")
lines=data.decode().split("\n")
nv=int(lines[1].split("= ")[1]);ev=int(lines[2].split("= ")[1]);enc=int(lines[3],16)

def oq(ct):
    sl(sock,"1");ru(sock,b"Ciphertext in hex: ");sl(sock,hex(ct))
    r=rl(sock).strip("()");dx,dy=r.split(",");return int(dx),int(dy)

all_ks=list(range(1,33));OR={}
for k in all_ks:OR[k]=oq((enc*pow(k,ev,nv))%nv)

def mt(k):
    def t(d,c):p=k*d+c;return(p%4,p//4,-1 if p%4==0 else(1 if p%4==1 else 0),1 if p%4==2 else(-1 if p%4==3 else 0))
    return t
def mr(k):
    def r(c):
        dx,dy=0,0
        while c>0:b=c%4;c//=4;dx+=[-1,1,0,0][b];dy+=[0,0,1,-1][b]
        return dx,dy
    return r

MAX_N=64
def bdp(k):
    t=mt(k);rf=mr(k);mc=min(k,6)
    dp=[{c:set() for c in range(mc+1)} for _ in range(MAX_N+1)]
    for c in range(mc+1):dp[0][c]={rf(c)}
    for N in range(1,MAX_N+1):
        for c in range(mc+1):
            res=set()
            for d in range(4):
                _,co,dxc,dyc=t(d,c)
                if co<=mc:
                    for(rdx,rdy)in dp[N-1][co]:res.add((dxc+rdx,dyc+rdy))
            dp[N][c]=res
    return dp

dp_k1=[set() for _ in range(MAX_N+1)]
for N in range(MAX_N+1):
    for dx in range(-N,N+1):
        for dy in range(-(N-abs(dx)),N-abs(dx)+1):
            if(N-abs(dx)-abs(dy))%2==0:dp_k1[N].add((dx,dy))

print("DP...");dp_k2=bdp(2);dp_k3=bdp(3);dp_k5=bdp(5);print("Done")

def idp1(s,dx,dy):return(dx,dy)in s or(dx+1,dy)in s
def idp23(d,c,dx,dy):
    if c not in d:return False
    s=d[c];return(dx,dy)in s or(dx+1,dy)in s

tk2=mt(2);tk3=mt(3);tk5=mt(5)

def toPath(x):
    s=bin(x)[2:]
    if len(s)%2==1:s="0"+s
    return "".join(directions[int(s[i:i+2],2)] for i in range(0,len(s),2))
def fp(p):return(p.count("R")-p.count("L"),p.count("U")-p.count("D"))
def fast_fp(x):
    if x==0:return(-1,0)
    L=x.bit_length();dx,dy=0,0
    if L%2==1:msb=(x>>(L-1))&1;dx+=1 if msb else -1;L-=1
    while L>0:
        c=(x>>(L-2))&3
        if c==0:dx-=1
        elif c==1:dx+=1
        elif c==2:dy+=1
        elif c==3:dy-=1
        L-=2
    return(dx,dy)

# Order digits by closeness to k=1 target
def digit_order(rem_dx,rem_dy,remaining):
    scores=[]
    for d in range(4):
        ndx=rem_dx-[-1,1,0,0][d];ndy=rem_dy-[0,0,1,-1][d]
        scores.append((abs(ndx)+abs(ndy),d))
    scores.sort()
    return[d for _,d in scores]

